class Solution {
  public boolean wordBreak(String s, List<String> wordDict) {
    int n = s.length();
    boolean[] dp = new boolean[n + 1];
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
      for (String w : wordDict) {
        int len = w.length();
        if (i >= len && dp[i - len] && s.startsWith(w, i - len)) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[n];
  }
}

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        n = len(s)
        dp = [False] * (n + 1)
        dp[0] = True
        for i in range(1, n + 1):
            for w in wordDict:
                if i >= len(w) and dp[i - len(w)] and s[i - len(w):i] == w:
                    dp[i] = True
                    break
        return dp[n]

use std::collections::HashSet;
impl Solution {
  pub fn word_break(s: String, word_dict: Vec<String>) -> bool {
    let n = s.len();
    let dict: HashSet<&str> = word_dict.iter().map(|w| w.as_str()).collect();
    let mut dp = vec![false; n + 1];
    dp[0] = true;
    for i in 1..=n {
      for j in 0..i {
        if dp[j] && dict.contains(&s[j..i]) {
          dp[i] = true;
          break;
        }
      }
    }
    dp[n]
  }
}

const wordBreak = (s: string, wordDict: string[]): boolean => {
  const n = s.length;
  const dp = new Array<boolean>(n + 1).fill(false);
  dp[0] = true;
  for (let i = 1; i <= n; i++) {
    for (const w of wordDict) {
      if (i >= w.length && dp[i - w.length] && s.slice(i - w.length, i) === w) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[n];
};
